'use client'

import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts'
import { chartGridStroke, chartAxisStroke, rechartsTooltipContentStyle, rechartsTooltipItemStyle } from '@/lib/chartStyles'
import { Card, WidgetTitleRow, EmptyChart } from './shared'
import DetailsButton from './DetailsButton'
import { formatDate } from '@/lib/utils'

const DETAIL_COLUMNS = [
  { key: 'name', label: 'Name' },
  { key: 'email', label: 'Email' },
  { key: 'phoneNumber', label: 'Phone' },
  { key: 'stage', label: 'Stage' },
  { key: 'createdAt', label: 'Created', format: (v) => formatDate(v) || '—' },
]

export default function BookingTrendWidget({ bookingRateTrend, paymentRateTrend, defaultRange }) {
  const trend = bookingRateTrend?.length ? bookingRateTrend : paymentRateTrend || []

  return (
    <Card>
      <WidgetTitleRow
        title="Booking Rate Trend"
        detailsButton={
          <DetailsButton
            title="Booking Rate Trend — full details"
            metric="leads"
            rangeDays={defaultRange}
            columns={DETAIL_COLUMNS}
          />
        }
      />
      {trend.length > 0 ? (
        <div className="mt-4 h-[240px]">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={trend} margin={{ top: 8, right: 20, left: 0, bottom: 0 }}>
              <defs>
                <linearGradient id="bookingFill" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="var(--bar-gradient-start)" stopOpacity={0.45} />
                  <stop offset="100%" stopColor="var(--bar-gradient-start)" stopOpacity={0} />
                </linearGradient>
              </defs>
              <CartesianGrid stroke={chartGridStroke} vertical={false} />
              <XAxis dataKey="week" tick={{ fill: chartAxisStroke, fontSize: 12 }} tickLine={false} axisLine={false} />
              <YAxis
                tick={{ fill: chartAxisStroke, fontSize: 12 }}
                tickLine={false}
                axisLine={false}
                tickFormatter={(v) => `${v}%`}
                domain={[0, 100]}
              />
              <Tooltip
                contentStyle={rechartsTooltipContentStyle}
                itemStyle={rechartsTooltipItemStyle}
                formatter={(v) => [`${v}%`, 'Rate']}
              />
              <Area
                type="monotone"
                dataKey="rate"
                stroke="var(--bar-gradient-start)"
                strokeWidth={2}
                fill="url(#bookingFill)"
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      ) : (
        <EmptyChart />
      )}
    </Card>
  )
}
