'use client'

import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts'
import { chartGridStroke, chartAxisStroke, rechartsTooltipContentStyle, rechartsTooltipCursor, rechartsTooltipItemStyle } from '@/lib/chartStyles'
import { Card, WidgetTitleRow, EmptyChart } from './shared'
import DetailsButton from './DetailsButton'
import { formatDate } from '@/lib/utils'

const DETAIL_COLUMNS = [
  { key: 'name', label: 'Name' },
  { key: 'email', label: 'Email' },
  { key: 'phoneNumber', label: 'Phone' },
  { key: 'uploadType', label: 'Source' },
  { key: 'stage', label: 'Stage' },
  { key: 'createdAt', label: 'Created', format: (v) => formatDate(v) || '—' },
]

export default function LeadsBySourceWidget({ leadsBySourceConversion = [], defaultRange }) {
  const data = leadsBySourceConversion.map((r) => ({
    name: r.leadSource,
    value: r.totalLeads,
  }))

  return (
    <Card>
      <WidgetTitleRow
        title="Lead Sources"
        detailsButton={
          <DetailsButton
            title="Lead Sources — full details"
            metric="leads"
            rangeDays={defaultRange}
            columns={DETAIL_COLUMNS}
          />
        }
      />
      {data.length > 0 ? (
        <div className="mt-4 h-[240px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={data} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
              <defs>
                <linearGradient id="dashLeadBarGradient" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="var(--bar-gradient-start)" />
                  <stop offset="100%" stopColor="var(--bar-gradient-end)" />
                </linearGradient>
              </defs>
              <CartesianGrid stroke={chartGridStroke} vertical={false} />
              <XAxis dataKey="name" tick={{ fill: chartAxisStroke, fontSize: 12 }} tickLine={false} axisLine={false} />
              <YAxis tick={{ fill: chartAxisStroke, fontSize: 12 }} tickLine={false} axisLine={false} />
              <Tooltip
                contentStyle={rechartsTooltipContentStyle}
                cursor={rechartsTooltipCursor}
                itemStyle={rechartsTooltipItemStyle}
              />
              <Bar dataKey="value" name="Leads" radius={[8, 8, 0, 0]} fill="url(#dashLeadBarGradient)" />
            </BarChart>
          </ResponsiveContainer>
        </div>
      ) : (
        <EmptyChart message="No leads in this period." />
      )}
    </Card>
  )
}
